import{_ as a,o as e,c as r,ag as d}from"./chunks/framework.Aev9KvMf.js";const b=JSON.parse('{"title":"官方公共数据库导航 · 家庭实用版","description":"家庭实用的官方公共数据库导航：法律法规全文库、老赖/涉诉查询、宏观统计数据、灾害预警、地理信息，全部一级来源。","frontmatter":{"title":"官方公共数据库导航 · 家庭实用版","issuer":"全国人大常委会办公厅 / 最高法 / 国家发改委 / 国家统计局 / 中国气象局 / 自然资源部等","source_tier":"一级来源","version":"—","published":"—","source_url":"https://flk.npc.gov.cn/","status":"现行服务","tags":["权威数据","公共数据库","法律法规","信用","统计","预警"],"type":"数据页","reviewed":false,"description":"家庭实用的官方公共数据库导航：法律法规全文库、老赖/涉诉查询、宏观统计数据、灾害预警、地理信息，全部一级来源。"},"headers":[],"relativePath":"data/official-databases.md","filePath":"data/official-databases.md"}'),o={name:"data/official-databases.md"};function n(h,t,s,l,i,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="官方公共数据库导航-·-家庭实用版" tabindex="-1">官方公共数据库导航 · 家庭实用版 <a class="header-anchor" href="#官方公共数据库导航-·-家庭实用版" aria-label="Permalink to &quot;官方公共数据库导航 · 家庭实用版&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">待核验</p><p>本页为导航索引（主要入口经浏览器核验可达，个别站点较慢已标注）；各库覆盖范围以官方说明为准。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>收录原则：只收<strong>普通家庭用得上的官方公共数据库</strong>（一级来源），科研级平台不展开（见文末）；本站只导航不代查。</p></div><h2 id="查法律法规原文" tabindex="-1">查法律法规原文 <a class="header-anchor" href="#查法律法规原文" aria-label="Permalink to &quot;查法律法规原文&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据库</th><th>查什么</th><th>入口</th></tr></thead><tbody><tr><td><strong>国家法律法规数据库</strong>（全国人大常委会办公厅）</td><td>现行宪法、法律、行政法规、地方性法规、司法解释<strong>免费全文</strong>——劳动合同法、消费者权益保护法等原文都在这</td><td><a href="https://flk.npc.gov.cn/" target="_blank" rel="noreferrer">flk.npc.gov.cn</a>（已核验）</td></tr></tbody></table><h2 id="查信用与涉诉-借钱-合伙-加盟前三查" tabindex="-1">查信用与涉诉（借钱/合伙/加盟前三查） <a class="header-anchor" href="#查信用与涉诉-借钱-合伙-加盟前三查" aria-label="Permalink to &quot;查信用与涉诉（借钱/合伙/加盟前三查）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据库</th><th>查什么</th><th>入口</th></tr></thead><tbody><tr><td><strong>中国执行信息公开网</strong>（最高人民法院）</td><td><strong>失信被执行人</strong>（老赖）、被执行人、限制消费人员名单——借大钱、合伙、招加盟商前必查</td><td><a href="http://zxgk.court.gov.cn/" target="_blank" rel="noreferrer">zxgk.court.gov.cn</a>（已核验）</td></tr><tr><td><strong>信用中国</strong>（国家公共信用信息中心）</td><td>全量行政处罚、失信黑名单、信用红名单的统一查询</td><td><a href="https://www.creditchina.gov.cn/" target="_blank" rel="noreferrer">creditchina.gov.cn</a>（已核验）</td></tr><tr><td><strong>中国裁判文书网</strong>（最高人民法院）</td><td>企业/个人的涉诉文书（公开范围以最高法规定为准，近年有所收紧）</td><td><a href="https://wenshu.court.gov.cn/" target="_blank" rel="noreferrer">wenshu.court.gov.cn</a></td></tr></tbody></table><p>配套：企业注册与经营异常另见<a href="/SageRelay/query/enterprise-credit.html">企业信用查询</a>（gsxt，两套系统互补）。</p><h2 id="查宏观数据" tabindex="-1">查宏观数据 <a class="header-anchor" href="#查宏观数据" aria-label="Permalink to &quot;查宏观数据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据库</th><th>查什么</th><th>入口</th></tr></thead><tbody><tr><td><strong>国家数据</strong>（国家统计局）</td><td>CPI、平均工资、人口、GDP 等权威统计——<strong>社平工资正是社保基数、误工费赔偿的计算基础</strong></td><td><a href="https://data.stats.gov.cn/" target="_blank" rel="noreferrer">data.stats.gov.cn</a>（已核验）</td></tr></tbody></table><h2 id="查灾害与预警" tabindex="-1">查灾害与预警 <a class="header-anchor" href="#查灾害与预警" aria-label="Permalink to &quot;查灾害与预警&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据库</th><th>查什么</th><th>入口</th></tr></thead><tbody><tr><td><strong>国家预警信息发布中心</strong>（气象局牵头，12379）</td><td>台风暴雨等<strong>官方预警</strong>发布（比商业天气 App 的推送更权威）</td><td><a href="https://www.12379.cn/" target="_blank" rel="noreferrer">www.12379.cn</a>（站点较慢，未确认可达）</td></tr><tr><td><strong>中国气象数据网</strong>（中国气象局）</td><td>气象科学数据与产品</td><td><a href="https://data.cma.cn/" target="_blank" rel="noreferrer">data.cma.cn</a></td></tr><tr><td>中国地震台网（中国地震台网中心）</td><td>地震速报与目录</td><td><a href="https://news.ceic.ac.cn/" target="_blank" rel="noreferrer">ceic.ac.cn</a>（待核验）</td></tr></tbody></table><h2 id="查地理" tabindex="-1">查地理 <a class="header-anchor" href="#查地理" aria-label="Permalink to &quot;查地理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据库</th><th>查什么</th><th>入口</th></tr></thead><tbody><tr><td><strong>天地图</strong>（自然资源部）</td><td>国家级地理信息公共服务——许多部门&quot;一张图&quot;的底座</td><td><a href="https://www.tianditu.gov.cn/" target="_blank" rel="noreferrer">tianditu.gov.cn</a>（已核验）</td></tr></tbody></table><h2 id="本站已收录的专项官方库-直达" tabindex="-1">本站已收录的专项官方库（直达） <a class="header-anchor" href="#本站已收录的专项官方库-直达" aria-label="Permalink to &quot;本站已收录的专项官方库（直达）&quot;">​</a></h2><p>药品/化妆品/器械（<a href="/SageRelay/query/drug.html">NMPA 查询</a>）· 食品抽检（<a href="/SageRelay/query/food-spot-check.html">食安查</a>）· 企业信用（<a href="/SageRelay/query/enterprise-credit.html">gsxt</a>）· 食品安全国家标准（<a href="/SageRelay/standards/gb28050-nutrition-label.html">全文公开系统</a>）· 空气与水质（<a href="/SageRelay/query/environment.html">环境查询</a>）· 最低工资（<a href="/SageRelay/data/minimum-wage-2026.html">人社部发布</a>）。</p><h2 id="科研级平台-收录边界说明" tabindex="-1">科研级平台（收录边界说明） <a class="header-anchor" href="#科研级平台-收录边界说明" aria-label="Permalink to &quot;科研级平台（收录边界说明）&quot;">​</a></h2><p>国家科技基础条件平台（中国科技资源共享网）、20 家国家科学数据中心、国家公共数据资源登记平台等<strong>科研/数据要素类</strong>平台确实存在且开放，但超出&quot;家庭实用&quot;边界，按 ADR 0001 域纪律暂不展开——需要时点名再深挖。</p><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>来源</td><td>全国人大常委会办公厅、最高人民法院、国家公共信用信息中心、国家统计局、中国气象局、自然资源部官网（均为一级来源）</td></tr><tr><td>核验</td><td>flk / zxgk / creditchina / data.stats / tianditu 已浏览器核验；12379 两次超时未确认</td></tr></tbody></table>',20)])])}const f=a(o,[["render",n]]);export{b as __pageData,f as default};
